        impl Figure { # [doc = " Creates an empty figure"] pub fn new () -> Figure { Figure { alpha : None , axes : map :: axis :: Map :: new () , box_width : None , font : None , font_size : None , key : None , output : Cow :: Borrowed (Path :: new ("output.plot")) , plots : Vec :: new () , size : None , terminal : Terminal :: Svg , tics : map :: axis :: Map :: new () , title : None , } } fn script (& self) -> Vec < u8 > { let mut s = String :: new () ; s . push_str (& format ! ("set output '{}'\n" , self . output . display () . to_string () . replace ('\'' , "''"))) ; if let Some (width) = self . box_width { s . push_str (& format ! ("set boxwidth {}\n" , width)) } if let Some (ref title) = self . title { s . push_str (& format ! ("set title '{}'\n" , title)) } for axis in self . axes . iter () { s . push_str (& axis . script ()) ; } for (_ , script) in self . tics . iter () { s . push_str (script) ; } if let Some (ref key) = self . key { s . push_str (& key . script ()) } if let Some (alpha) = self . alpha { s . push_str (& format ! ("set style fill transparent solid {}\n" , alpha)) } s . push_str (& format ! ("set terminal {} dashed" , self . terminal . display ())) ; if let Some ((width , height)) = self . size { s . push_str (& format ! (" size {}, {}" , width , height)) } if let Some (ref name) = self . font { if let Some (size) = self . font_size { s . push_str (& format ! (" font '{},{}'" , name , size)) } else { s . push_str (& format ! (" font '{}'" , name)) } } s . push_str ("\nunset bars\n") ; let mut is_first_plot = true ; for plot in & self . plots { let data = plot . data () ; if data . bytes () . is_empty () { continue ; } if is_first_plot { s . push_str ("plot ") ; is_first_plot = false ; } else { s . push_str (", ") ; } s . push_str (& format ! ("'-' binary endian=little record={} format='%float64' using " , data . nrows ())) ; let mut is_first_col = true ; for col in 0 .. data . ncols () { if is_first_col { is_first_col = false ; } else { s . push (':') ; } s . push_str (& (col + 1) . to_string ()) ; } s . push (' ') ; s . push_str (plot . script ()) ; } let mut buffer = s . into_bytes () ; let mut is_first = true ; for plot in & self . plots { if is_first { is_first = false ; buffer . push (b'\n') ; } buffer . extend_from_slice (plot . data () . bytes ()) ; } buffer } # [doc = " Spawns a drawing child process"] # [doc = ""] # [doc = " NOTE: stderr, stdin, and stdout are piped"] pub fn draw (& mut self) -> io :: Result < Child > { use std :: process :: Stdio ; let mut gnuplot = Command :: new ("gnuplot") . stderr (Stdio :: piped ()) . stdin (Stdio :: piped ()) . stdout (Stdio :: piped ()) . spawn () ? ; self . dump (gnuplot . stdin . as_mut () . unwrap ()) ? ; Ok (gnuplot) } # [doc = " Dumps the script required to produce the figure into `sink`"] pub fn dump < W > (& mut self , sink : & mut W) -> io :: Result < & mut Figure > where W : io :: Write , { sink . write_all (& self . script ()) ? ; Ok (self) } # [doc = " Saves the script required to produce the figure to `path`"] pub fn save (& self , path : & Path) -> io :: Result < & Figure > { use std :: io :: Write ; File :: create (path) ? . write_all (& self . script ()) ? ; Ok (self) } }
